css:
/* Hide a specific element in print view */
.text-center h4 {
    display: none;
}
.print-format td, .print-format th {
    padding: 4px !important;
}
@page {
    margin-bottom: 30mm;
}

.footer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    height: 20mm;
    font-size: 11px;
    border-top: 1px solid #999;
    padding-top: 4mm;
}

.page-number:before {
    content: counter(page);
}

.total-pages:before {
    content: counter(pages);
}

html:
{% set result = frappe.call('lexta.api.prepared_doc_data.get_general_ledger_prepared_data') %}

{% set filters = result.get("applied_filters", {}) %}
{% set balances = result.get("balance_details", {}) %}
{% set data = result.get("data", []) %}

{% set party = filters.get("party") %}
{% set party_type = filters.get("party_type") %}
{% set company = filters.get("company") %}

{% set header_name = "" %}
{% set party_code = "" %}
{% set party_name = "" %}
{% set address = "" %}

{% set from_date = frappe.utils.formatdate(filters.get("from_date"), "dd MMM yyyy") %}
{% set to_date = frappe.utils.formatdate(filters.get("to_date"), "dd MMM yyyy") %}

{% set opening_balance = balances.get("opening", {}).get("balance", 0) %}
{% set total_debit = balances.get("total", {}).get("debit", 0) %}
{% set total_credit = balances.get("total", {}).get("credit", 0) %}
{% set closing_balance = balances.get("total", {}).get("balance", 0) %}

{% set account_filter = filters.get("account") %}
{% set is_account_filter = account_filter and account_filter|length > 0 %}

{% if is_account_filter %}

    {% set header_name = "ACCOUNT LEDGER STATEMENT" %}

    {% set account_list = account_filter %}

    {% if account_list is string %}
        {% set account_list = [account_list] %}
    {% endif %}

    {% set account_names = [] %}

    {% for acc in account_list %}

        {% set acc_doc = frappe.get_doc("Account", acc) %}
        {% set _ = account_names.append(acc_doc.account_name) %}

    {% endfor %}

    {% set party_name = account_names %}

{% else %}

    {% if party and party_type == "Supplier" %}

        {% set header_name = "SERVICE PROVIDER LEDGER" %}

        {% set is_nmicl = company == "Nationwide Medical Insurance Company limited" %}

        {% if is_nmicl %}

            {% set party_parts = party.split(' ', 1) %}
            {% set party_code = party_parts[0] %}
            {% set party_name = party_parts[1] if party_parts|length > 1 else "" %}

        {% else %}

            {% set party_name = party %}

        {% endif %}

        {% set supplier_doc = frappe.get_doc("Supplier", party) %}
        {% set address = supplier_doc.custom_postal_address or "" %}

    {% endif %}

    {% if party and party_type == "Customer" %}

        {% set header_name = "CUSTOMER STATEMENT" %}

        {% set customer_doc = frappe.get_doc("Customer", party) %}
        {% set party_name = customer_doc.name %}
        {% set address = customer_doc.custom_ghana_post_address or "" %}

    {% endif %}

{% endif %}

<div style="width: 100%; overflow: hidden;">
    <div style="float: left; width: 65%;">

    </div>

    <div style="float: right; width: 35%; text-align: right;">
        <img src="/files/lexta leteerhead for approval-2.jpgf69318.jpeg" style="max-height: 80px;">
    </div>
</div>

<div id="header-html" class="hidden-pdf" style="margin-top: 100px;"></div>

<table style="margin-top:-10px;
              table-layout:fixed;
              width:100%;">

    <tr>

        <td colspan="14"
            rowspan="2"
            style="vertical-align:middle !important;
                   text-align:center;
                   font-weight:bold;">

            {{ header_name }}

        </td>

        <td colspan="4"
            style="font-size:12px;
                   text-align:right;">

            <b>From</b> : {{ from_date }}

        </td>

    </tr>

    <tr>

        <td colspan="4"
            style="font-size:12px;
                   text-align:right;">

            <b>To</b> : {{ to_date }}

        </td>

    </tr>

</table>

<table style="margin-top:-5px;
              width:100%;
              border-top:1px solid black;
              font-size:11px;">

    <tr>

        <td style="width:5%;"><b>ID:</b></td>

        <td style="width:25%;">
            {{ party_code }}
        </td>

        <td style="width:7%;">
            <b>Name:</b>
        </td>

        <td style="width:25%;">

            {% if is_account_filter %}

                {% for name in party_name %}
                    <div>{{ name }}</div>
                {% endfor %}

            {% else %}

                {{ party_name }}

            {% endif %}

        </td>

        <td style="width:38%; text-align:right;">

            {% set cost_center = filters.get("cost_center") %}

            {% if cost_center %}

                {% if cost_center is string %}
                    {% set cost_center_list = [cost_center] %}
                {% else %}
                    {% set cost_center_list = cost_center %}
                {% endif %}

                {% for cc in cost_center_list %}

                    {% set cc_name = cc.split(' - ')[0] if ' - ' in cc else cc %}

                    <div>{{ cc_name }}</div>

                {% endfor %}

            {% endif %}

        </td>

    </tr>

    {% if not is_account_filter %}

    <tr>

        <td colspan="4">

            <b>Address:</b> {{ address }}

        </td>

    </tr>

    {% endif %}

</table>

<table style="table-layout:fixed;
              width:100%;
              margin-top:10px;
              border-collapse:collapse;
              border-top:1px solid #000;
              font-size:11px;">

    <!-- Header -->
    <tr style="font-weight:bold; border-bottom:1px solid #000;">

        <td colspan="2"><b>Date</b></td>
        <td colspan="2"><b>Doc. Number</b></td>
        <td colspan="5"><b>Description</b></td>
        <td colspan="2" style="text-align:right;"><b>Cheque#</b></td>
        <td colspan="2" style="text-align:right;"><b>Debit</b></td>
        <td colspan="2" style="text-align:right;"><b>Credit</b></td>
        <td colspan="3" style="text-align:right;"><b>Balance GHS</b></td>

    </tr>

    <!-- Opening Balance -->
    <tr>

        <td colspan="15">
            Balance Brought Forward
        </td>

        <td colspan="3" style="text-align:right;">

            {% if opening_balance < 0 %}
                ({{ "{:,.2f}".format(opening_balance | abs) }})
            {% else %}
                {{ "{:,.2f}".format(opening_balance) }}
            {% endif %}

        </td>

    </tr>

    <!-- Ledger Rows -->
    {% for i in data %}

    {% set bal = i.get("balance", 0) %}

    <tr style="background-color:{% if loop.index is odd %}#dedede{% else %}#ffffff{% endif %};">

        <td colspan="2">
            {{ frappe.utils.formatdate(i.get("posting_date"), "dd MMM yyyy") }}
        </td>

        <td colspan="2">
            {{ i.get("doc_name", "") }}
        </td>

        <td colspan="5">
            {{ i.get("narration", "") }}
        </td>

        <td colspan="2" style="text-align:right;">
            {{ i.get("cheque_no", "") }}
        </td>

        <td colspan="2" style="text-align:right;">
            {{ "{:,.2f}".format(i.get("debit", 0)) }}
        </td>

        <td colspan="2" style="text-align:right;">
            {{ "{:,.2f}".format(i.get("credit", 0)) }}
        </td>

        <td colspan="3" style="text-align:right;">

            {% if bal < 0 %}
                ({{ "{:,.2f}".format(bal | abs) }})
            {% else %}
                {{ "{:,.2f}".format(bal) }}
            {% endif %}

        </td>

    </tr>

    {% endfor %}

    <!-- Totals -->
    <tr style="border-top:1px solid #000;">

        <td colspan="11"></td>

        <td colspan="2" style="text-align:right;">
            <b>{{ "{:,.2f}".format(total_debit) }}</b>
        </td>

        <td colspan="2" style="text-align:right;">
            <b>{{ "{:,.2f}".format(total_credit) }}</b>
        </td>

        <td colspan="3"></td>

    </tr>

    <!-- Closing Balance -->
    <tr>

        <td colspan="12"></td>

        <td colspan="2">
            <b>Balance:</b>
        </td>

        <td colspan="4" style="text-align:right;">

            <b>
                {% if closing_balance < 0 %}
                    ({{ "{:,.2f}".format(closing_balance | abs) }})
                {% else %}
                    {{ "{:,.2f}".format(closing_balance) }}
                {% endif %}
            </b>

        </td>

    </tr>

    <!-- Generated By -->
    <tr>

        <td colspan="18">

            {% set user_doc = frappe.get_doc("User", frappe.session.user) %}

            <b>Generated By:</b>

            <span style="border-bottom:1px dotted #000;
                         padding:5px 80px 5px 30px;">

                {{ user_doc.full_name.upper() }}

            </span>

        </td>

    </tr>

    <tr width="width:100% !important;" style="margin-top:20px">
        <td colspan="18">
            <img src="/files/lexta leteerhead for approval-2.jpg.jpeg" >
        </td>
    </tr>

</table>
